function UIBattlingTotalDamageGlobal:Awake()
    self.eventBattleDamageShow = Events.AddListener(Constants.EventNames.BattleDamageShow, Bind(self, self.OnDamage))
end

function UIBattlingTotalDamageGlobal:Start()
end

function UIBattlingTotalDamageGlobal:OnDestroy()
    Events.RemoveListener(Constants.EventNames.BattleDamageShow, self.eventBattleDamageShow)
