------------ lifeCycle ------------


function UIBattlingTotalDamageGlobal:CleanProperties()
    self.eventBattleDamageShow = nil
    self.totalDamage = nil
end

function UIBattlingTotalDamageGlobal:OnDamage(data)
    -- 这里如果角色死了，表现层就找不到这个角色了，这会导致没有统计到角色死后dot造成的伤害，所以这里从逻辑层获取角色阵营
    local attackerCamp = BattleMgr:GetRoleCampWithSpecialSummon(data.attackerId)
    if attackerCamp == nil then return end
    -- local attackerCamp = UIBattlingDataMgr:GetRoleCampByRoleId(data.attackerId)
    -- 只计算攻击者为友方的（和伤害统计的逻辑保持一致）
    if not BattleInfo:IsUserCamp(attackerCamp) then return end
    --- 治疗不计
    if data.damage < 0 then return end
    local damage = data.hpChange + data.shieldAbsorb
    self.totalDamage = (self.totalDamage or 0) + math.modf(damage)

    CfUtils.FillText(self.TxtNum, tostring(self.totalDamage))
end

return UIBattlingTotalDamageGlobal